import { z } from 'zod';

export const ArmSchema = z.enum(['baseline', 'skill', 'mcp']);
export type Arm = z.infer<typeof ArmSchema>;

export const ArmConfigSchema = z.object({
  id: ArmSchema,
  description: z.string(),
  // Passed to --mcp-config alongside --strict-mcp-config. Either an inline JSON
  // string ({"mcpServers":{}} for "none") or a path resolved against rootDir.
  mcpConfig: z.string(),
  // Optional positive allowlist. Used by strict methodology runs to keep each
  // arm's tool surface as small as possible.
  allowedTools: z.array(z.string()).optional(),
  // Tools that should be denied for this arm (e.g. ["Skill","Bash"]). Always
  // joined with WebFetch/WebSearch to close URL-fetch shortcuts across arms.
  disallowedTools: z.array(z.string()),
  // Escape hatch for additional flags discovered during verify-arms.
  extraFlags: z.array(z.string()),
});
export type ArmConfig = z.infer<typeof ArmConfigSchema>;

// All arms strip user-level settings (which would otherwise leak skills like
// agent-browser into the experiment) and bypass permissions so MCP servers
// and tools work without interactive prompts.
const COMMON_FLAGS = ['--setting-sources', 'project,local', '--permission-mode', 'bypassPermissions'];

// Always-blocked tools across every arm:
// - WebFetch / WebSearch: closes the "fetch the page via HTTP and parse HTML
//   directly" shortcut. The experiment is supposed to measure browser-tool
//   use, not URL fetching.
// - Monitor / CronCreate / RemoteTrigger: each is a process-execution channel
//   (Monitor takes `command`, CronCreate schedules shell jobs, RemoteTrigger
//   invokes remote agents). The agent will use any of them to spawn arbitrary
//   processes if Bash itself is blocked.
const ALWAYS_BLOCKED = ['WebFetch', 'WebSearch', 'Monitor', 'CronCreate', 'RemoteTrigger'];

export const armConfigs: Record<Arm, ArmConfig> = {
  baseline: {
    id: 'baseline',
    description: 'No browser tools — pure reasoning floor (no Bash, no Agent: Agent spawns a subagent that has Bash, no Monitor: takes a command and executes it)',
    mcpConfig: '{"mcpServers":{}}',
    disallowedTools: ['Skill', 'Bash', 'Agent', ...ALWAYS_BLOCKED],
    extraFlags: [...COMMON_FLAGS],
  },
  skill: {
    id: 'skill',
    description: 'Playwright CLI Skill enabled, no MCP server',
    mcpConfig: '{"mcpServers":{}}',
    // Skill+Bash legitimately required by the playwright-cli skill. Agent
    // kept available — blocking it broke Skill tool invocation in testing.
    disallowedTools: [...ALWAYS_BLOCKED],
    extraFlags: [...COMMON_FLAGS],
  },
  mcp: {
    id: 'mcp',
    description: 'Playwright MCP server enabled, no skills, no Bash',
    mcpConfig: '.mcp.json',
    // Skill blocked; Bash blocked too — mcp__playwright__browser_take_screenshot
    // accepts a `filename` parameter, so no shell-out is needed for file moves.
    // Closes the curl-bypass cheat path that previously survived in this arm.
    // Agent kept for symmetry with skill arm.
    disallowedTools: ['Skill', 'Bash', ...ALWAYS_BLOCKED],
    extraFlags: [...COMMON_FLAGS],
  },
};

export const strictArmConfigs: Record<Arm, ArmConfig> = {
  baseline: {
    ...armConfigs.baseline,
    description: 'Strict baseline — no browser, shell, skill, or sub-agent execution path',
    allowedTools: ['ToolSearch', 'Read', 'Glob', 'Grep', 'Write', 'TodoWrite'],
    disallowedTools: ['Skill', 'Bash', 'Task', 'Agent', ...ALWAYS_BLOCKED],
  },
  skill: {
    ...armConfigs.skill,
    description: 'Strict Playwright CLI Skill — only Playwright CLI shell commands plus file output',
    allowedTools: [
      'ToolSearch',
      'Skill',
      'Bash(playwright-cli:*)',
      'Write',
      'TodoWrite',
    ],
    disallowedTools: ['Task', 'Agent', ...ALWAYS_BLOCKED],
  },
  mcp: {
    ...armConfigs.mcp,
    description: 'Strict Playwright MCP — MCP browser tools only, no Skill or Bash',
    allowedTools: [
      'ToolSearch',
      'Write',
      'TodoWrite',
      'mcp__playwright__browser_click',
      'mcp__playwright__browser_close',
      'mcp__playwright__browser_console_messages',
      'mcp__playwright__browser_drag',
      'mcp__playwright__browser_drop',
      'mcp__playwright__browser_evaluate',
      'mcp__playwright__browser_file_upload',
      'mcp__playwright__browser_fill_form',
      'mcp__playwright__browser_handle_dialog',
      'mcp__playwright__browser_hover',
      'mcp__playwright__browser_navigate',
      'mcp__playwright__browser_navigate_back',
      'mcp__playwright__browser_network_request',
      'mcp__playwright__browser_network_requests',
      'mcp__playwright__browser_press_key',
      'mcp__playwright__browser_resize',
      'mcp__playwright__browser_run_code_unsafe',
      'mcp__playwright__browser_select_option',
      'mcp__playwright__browser_snapshot',
      'mcp__playwright__browser_tabs',
      'mcp__playwright__browser_take_screenshot',
      'mcp__playwright__browser_type',
      'mcp__playwright__browser_wait_for',
    ],
    disallowedTools: ['Skill', 'Bash', 'Task', 'Agent', ...ALWAYS_BLOCKED],
  },
};

export function getArmConfig(arm: Arm, runName?: string): ArmConfig {
  return runName ? strictArmConfigs[arm] : armConfigs[arm];
}

export const ExperimentConfigSchema = z.object({
  name: z.string(),
  model: z.string().default('claude-sonnet-4-6'),
  maxTurns: z.number().int().positive().default(20),
});
export type ExperimentConfig = z.infer<typeof ExperimentConfigSchema>;

export const defaultExperimentConfig: ExperimentConfig = {
  name: 'playwright',
  model: 'claude-sonnet-4-6',
  maxTurns: 20,
};

