1	import { randomBytes } from 'node:crypto';
2	import { readFile } from 'node:fs/promises';
3	import { dirname, join } from 'node:path';
4	import { fileURLToPath } from 'node:url';
5	import type { IncomingMessage, ServerResponse } from 'node:http';
6	import type { Task, TaskContext } from '../../../harness/src/tasks.js';
7	import {
8	  genCheckoutState,
9	  genRecoveryState,
10	  type CheckoutState,
11	  type CheckoutSession,
12	  type RecoveryState,
13	} from '../../../harness/src/trialState.js';
14	
15	const __dirname = dirname(fileURLToPath(import.meta.url));
16	const FIXTURES_DIR = join(__dirname, '..', 'fixtures');
17	
18	const tplCache = new Map<string, string>();
19	async function loadTemplate(rel: string): Promise<string> {
20	  let tpl = tplCache.get(rel);
21	  if (tpl === undefined) {
22	    tpl = await readFile(join(FIXTURES_DIR, rel), 'utf-8');
23	    tplCache.set(rel, tpl);
24	  }
25	  return tpl;
26	}
27	
28	function applyTemplate(tpl: string, vars: Record<string, string>): string {
29	  let out = tpl;
30	  for (const [k, v] of Object.entries(vars)) {
31	    out = out.replaceAll(`{{${k}}}`, v);
32	  }
33	  return out;
34	}
35	
36	function escapeHtml(s: string): string {
37	  return s.replace(/[&<>"']/g, c => (
38	    { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]!
39	  ));
40	}
41	
42	function urlPath(req: IncomingMessage): string {
43	  const raw = req.url ?? '/';
44	  const q = raw.indexOf('?');
45	  return q >= 0 ? raw.slice(0, q) : raw;
46	}
47	
48	function parseCookies(req: IncomingMessage): Record<string, string> {
49	  const header = req.headers.cookie;
50	  if (!header) return {};
51	  const out: Record<string, string> = {};
52	  for (const part of header.split(';')) {
53	    const eq = part.indexOf('=');
54	    if (eq < 0) continue;
55	    out[part.slice(0, eq).trim()] = decodeURIComponent(part.slice(eq + 1).trim());
56	  }
57	  return out;
58	}
59	
60	function sendHtml(
61	  res: ServerResponse,
62	  html: string,
63	  status = 200,
64	  extraHeaders: Record<string, string | string[]> = {},
65	): void {
66	  res.writeHead(status, {
67	    'Content-Type': 'text/html; charset=utf-8',
68	    'Cache-Control': 'no-store',
69	    ...extraHeaders,
70	  });
71	  res.end(html);
72	}
73	
74	function sendStatus(res: ServerResponse, status: number, msg = ''): void {
75	  res.writeHead(status, { 'Content-Type': 'text/plain; charset=utf-8' });
76	  res.end(msg);
77	}
78	
79	function sendRedirect(
80	  res: ServerResponse,
81	  location: string,
82	  extraHeaders: Record<string, string | string[]> = {},
83	): void {
84	  // 303 See Other so POST → GET on follow.
85	  res.writeHead(303, { Location: location, ...extraHeaders });
86	  res.end();
87	}
88	
89	function parseBody(req: IncomingMessage, body: Buffer): Record<string, string> {
90	  const ctype = (req.headers['content-type'] ?? '').toLowerCase();
91	  const text = body.toString('utf-8');
92	  const out: Record<string, string> = {};
93	  if (ctype.includes('application/json')) {
94	    try {
95	      const obj = JSON.parse(text);
96	      if (obj && typeof obj === 'object') {
97	        for (const [k, v] of Object.entries(obj)) out[k] = String(v);
98	      }
99	    } catch {
100	      /* swallow */
101	    }
102	  } else {
103	    for (const [k, v] of new URLSearchParams(text)) out[k] = v;
104	  }
105	  return out;
106	}
107	
108	function readSid(req: IncomingMessage): string | null {
109	  return parseCookies(req).sid ?? null;
110	}
111	
112	function newSid(): string {
113	  return randomBytes(8).toString('hex');
114	}
115	
116	function setSidCookie(sid: string): string {
117	  return `sid=${sid}; Path=/; HttpOnly; SameSite=Lax`;
118	}
119	
120	async function readJsonIfExists<T = unknown>(path: string): Promise<T | null> {
121	  try {
122	    const raw = await readFile(path, 'utf-8');
123	    return JSON.parse(raw) as T;
124	  } catch {
125	    return null;
126	  }
127	}
128	
129	async function readTextIfExists(path: string): Promise<string | null> {
130	  try {
131	    return await readFile(path, 'utf-8');
132	  } catch {
133	    return null;
134	  }
135	}
136	
137	// ---------------------------------------------------------------------------
138	// Task — tier2_checkout
139	// ---------------------------------------------------------------------------
140	
141	function ensureCheckoutSession(state: CheckoutState, req: IncomingMessage): { sid: string; sess: CheckoutSession; setCookie?: string } {
142	  let sid = readSid(req);
143	  let setCookie: string | undefined;
144	  if (!sid || !state.sessions.has(sid)) {
145	    sid = newSid();
146	    setCookie = setSidCookie(sid);
147	  }
148	  let sess = state.sessions.get(sid);
149	  if (!sess) {
150	    sess = { cart: [], stage: 'browsing' };
151	    state.sessions.set(sid, sess);
152	  }
153	  return { sid, sess, ...(setCookie ? { setCookie } : {}) };
154	}
155	
156	const tier2_checkout: Task = {
157	  id: 'tier2_checkout',
158	  tier: 2,
159	  setup: (seed) => genCheckoutState(seed),
160	
161	  renderResponse: async (rawState, req, res, body) => {
162	    const s = rawState as CheckoutState;
163	    const path = urlPath(req);
164	    if (!path.startsWith('/checkout/')) return false;
165	
166	    const { sid, sess, setCookie } = ensureCheckoutSession(s, req);
167	    const cookieHeader = setCookie ? { 'Set-Cookie': setCookie } : {};
168	
169	    // --- GET / (product list) -------------------------------------------
170	    if (path === '/checkout/index.html' || path === '/checkout/') {
171	      if (req.method !== 'GET') { sendStatus(res, 405, 'method not allowed'); return true; }
172	      const tpl = await loadTemplate('checkout/index.html.tmpl');
173	      const items = s.products.map(p => `
174	        <li class="product" data-product-id="${p.id}">
175	          <div class="product-title">${escapeHtml(p.title)}</div>
176	          <div class="price">${escapeHtml(p.price)}</div>
177	          <form method="POST" action="/checkout/add" style="margin-top:8px;">
178	            <input type="hidden" name="product_id" value="${p.id}" />
179	            <button type="submit" id="add-${p.id}">Add to cart</button>
180	          </form>
181	        </li>`).join('\n');
182	      sendHtml(res, applyTemplate(tpl, { PRODUCTS: items }), 200, cookieHeader);
183	      return true;
184	    }
185	
186	    // --- POST /checkout/add ---------------------------------------------
187	    if (path === '/checkout/add') {
188	      if (req.method !== 'POST') { sendStatus(res, 405, 'method not allowed'); return true; }
189	      const fields = parseBody(req, body);
190	      const pid = fields.product_id;
191	      if (!pid || !s.products.some(p => p.id === pid)) {
192	        sendStatus(res, 400, 'unknown product');
193	        return true;
194	      }
195	      sess.cart.push(pid);
196	      sendRedirect(res, '/checkout/cart', cookieHeader);
197	      return true;
198	    }
199	
200	    // --- GET /checkout/cart ---------------------------------------------
201	    if (path === '/checkout/cart') {
202	      if (req.method !== 'GET') { sendStatus(res, 405, 'method not allowed'); return true; }
203	      const tpl = await loadTemplate('checkout/cart.html.tmpl');
204	      let cartBody: string;
205	      if (sess.cart.length === 0) {
206	        cartBody = `<p class="empty" id="empty-cart">Your cart is empty.</p>`;
207	      } else {
208	        const rows = sess.cart.map(pid => {
209	          const p = s.products.find(x => x.id === pid)!;
210	          return `<tr><td>${escapeHtml(p.title)}</td><td>${escapeHtml(p.price)}</td></tr>`;
211	        }).join('\n');
212	        cartBody = `
213	          <table id="cart-table">
214	            <thead><tr><th>Item</th><th>Price</th></tr></thead>
215	            <tbody>${rows}</tbody>
216	          </table>
217	          <div class="actions">
218	            <a class="btn" id="checkout" href="/checkout/shipping">Proceed to checkout</a>
219	          </div>`;
220	      }
221	      sendHtml(res, applyTemplate(tpl, { CART_BODY: cartBody }), 200, cookieHeader);
222	      return true;
223	    }
224	
225	    // --- GET /checkout/shipping -----------------------------------------
226	    if (path === '/checkout/shipping') {
227	      if (req.method !== 'GET') { sendStatus(res, 405, 'method not allowed'); return true; }
228	      if (sess.cart.length === 0) {
229	        sendHtml(res, `<!doctype html><body><p id="error">Cart is empty. <a href="/checkout/index.html">Go back</a>.</p></body>`, 200, cookieHeader);
230	        return true;
231	      }
232	      const tpl = await loadTemplate('checkout/shipping.html.tmpl');
233	      sendHtml(res, applyTemplate(tpl, { ERROR: '' }), 200, cookieHeader);
234	      return true;
235	    }
236	
237	    // --- POST /checkout/shipping/submit ---------------------------------
238	    if (path === '/checkout/shipping/submit') {
239	      if (req.method !== 'POST') { sendStatus(res, 405, 'method not allowed'); return true; }
240	      if (sess.cart.length === 0) { sendStatus(res, 400, 'empty cart'); return true; }
241	      const fields = parseBody(req, body);
242	      const exp = s.expectedShipping;
243	      const got = {
244	        name: (fields.name ?? '').trim(),
245	        address: (fields.address ?? '').trim(),
246	        city: (fields.city ?? '').trim(),
247	        zip: (fields.zip ?? '').trim(),
248	      };
249	      const mismatched = (Object.keys(exp) as Array<keyof typeof exp>).filter(k => got[k] !== exp[k]);
250	      if (mismatched.length > 0) {
251	        const tpl = await loadTemplate('checkout/shipping.html.tmpl');
252	        const errHtml = `<div class="error" id="shipping-error">Please correct the following fields: ${mismatched.join(', ')}.</div>`;
253	        sendHtml(res, applyTemplate(tpl, { ERROR: errHtml }), 200, cookieHeader);
254	        return true;
255	      }
256	      sess.shipping = got;
257	      sess.stage = 'confirm';
258	      sendRedirect(res, '/checkout/confirm', cookieHeader);
259	      return true;
260	    }
261	
262	    // --- GET /checkout/confirm ------------------------------------------
263	    if (path === '/checkout/confirm') {
264	      if (req.method !== 'GET') { sendStatus(res, 405, 'method not allowed'); return true; }
265	      if (sess.stage !== 'confirm' || !sess.shipping) {
266	        sendHtml(res, `<!doctype html><body><p id="error">Shipping not completed yet. <a href="/checkout/shipping">Go back</a>.</p></body>`, 200, cookieHeader);
267	        return true;
268	      }
269	      const tpl = await loadTemplate('checkout/confirm.html.tmpl');
270	      const items = sess.cart.map(pid => {
271	        const p = s.products.find(x => x.id === pid)!;
272	        return `<tr><td>${escapeHtml(p.title)}</td><td>${escapeHtml(p.price)}</td></tr>`;
273	      }).join('\n');
274	      sendHtml(res, applyTemplate(tpl, {
275	        ITEMS: items,
276	        SHIP_NAME: escapeHtml(sess.shipping.name),
277	        SHIP_ADDRESS: escapeHtml(sess.shipping.address),
278	        SHIP_CITY: escapeHtml(sess.shipping.city),
279	        SHIP_ZIP: escapeHtml(sess.shipping.zip),
280	      }), 200, cookieHeader);
281	      return true;
282	    }
283	
284	    // --- POST /checkout/place_order -------------------------------------
285	    if (path === '/checkout/place_order') {
286	      if (req.method !== 'POST') { sendStatus(res, 405, 'method not allowed'); return true; }
287	      if (sess.stage !== 'confirm' || !sess.shipping || sess.cart.length === 0) {
288	        sendStatus(res, 400, 'cannot place order in current stage');
289	        return true;
290	      }
291	      const orderId = randomBytes(8).toString('hex'); // 16 hex
292	      sess.orderId = orderId;
293	      sess.stage = 'placed';
294	      s.placedOrders.push({ sid, orderId, productIds: [...sess.cart] });
295	      const tpl = await loadTemplate('checkout/success.html.tmpl');
296	      sendHtml(res, applyTemplate(tpl, { ORDER_ID: orderId }), 200, cookieHeader);
297	      return true;
298	    }
299	
300	    return false;
301	  },
302	
303	  prompt: (ctx: TaskContext) => {
304	    const sub = (ctx.state as CheckoutState).targetSubstring;
305	    return `
306	Navigate a browser to this URL:
307	  ${ctx.fixturesUrl}/checkout/index.html
308	
309	The page lists three products with titles of the form "Product-XXXXXX" (hex). Find the one whose title contains the substring "${sub}" (case-sensitive) and add it to your cart by clicking its "Add to cart" button.
310	
311	Then proceed through checkout:
312	  1. Open the cart and click "Proceed to checkout".
313	  2. Fill the shipping form with these exact values:
314	       Name:    Test User
315	       Address: 123 Main St
316	       City:    Springfield
317	       ZIP:     12345
318	     Click "Continue".
319	  3. On the order confirmation page, click "Place order".
320	
321	After the order is placed, the page displays a 16-character lowercase hex order ID inside an element with id="order-id".
322	
323	Save just the order ID (no surrounding text) to:
324	  ${ctx.outputDir}/order_id.txt
325	
326	When the file is written, you are done.
327	`.trim();
328	  },
329	
330	  successCheck: async (ctx) => {
331	    const path = join(ctx.outputDir, 'order_id.txt');
332	    const text = await readTextIfExists(path);
333	    const s = ctx.state as CheckoutState;
334	    const extras: Record<string, unknown> = {
335	      orders_placed: s.placedOrders.length,
336	      sessions_seen: s.sessions.size,
337	    };
338	    if (text === null) {
339	      return { pass: false, score: 0, notes: `missing ${path}`, extras };
340	    }
341	    const trimmed = text.trim();
342	    if (!/^[0-9a-f]{16}$/.test(trimmed)) {
343	      return {
344	        pass: false,
345	        score: 0.2,
346	        notes: `expected 16-hex order ID, got ${JSON.stringify(trimmed.slice(0, 80))}`,
347	        extras,
348	      };
349	    }
350	    const order = s.placedOrders.find(o => o.orderId === trimmed);
351	    if (!order) {
352	      return {
353	        pass: false,
354	        score: 0.3,
355	        notes: `order ID ${trimmed} was never issued by the server`,
356	        extras,
357	      };
358	    }
359	    if (!order.productIds.includes(s.targetProductId)) {
360	      return {
361	        pass: false,
362	        score: 0.6,
363	        notes: `order placed but did not contain the target product ${s.targetProductId} (cart was ${JSON.stringify(order.productIds)})`,
364	        extras,
365	      };
366	    }
367	    return { pass: true, score: 1, notes: 'order placed with target product', extras };
368	  },
369	};
370	
371	// ---------------------------------------------------------------------------
372	// Task — tier2_recovery
373	// ---------------------------------------------------------------------------
374	
375	function ensureRecoverySession(state: RecoveryState, req: IncomingMessage): { sid: string; setCookie?: string } {
376	  let sid = readSid(req);
377	  let setCookie: string | undefined;
378	  if (!sid || !state.sessions.has(sid)) {
379	    sid = newSid();
380	    setCookie = setSidCookie(sid);
381	    state.sessions.set(sid, { attempts: 0 });
382	  }
383	  return { sid, ...(setCookie ? { setCookie } : {}) };
384	}
385	
386	const tier2_recovery: Task = {
387	  id: 'tier2_recovery',
388	  tier: 2,
389	  setup: (seed) => genRecoveryState(seed),
390	
391	  renderResponse: async (rawState, req, res, body) => {
392	    const s = rawState as RecoveryState;
393	    const path = urlPath(req);
394	    if (!path.startsWith('/recovery/')) return false;
395	
396	    const { sid, setCookie } = ensureRecoverySession(s, req);
397	    const cookieHeader = setCookie ? { 'Set-Cookie': setCookie } : {};
398	
399	    // --- GET /recovery/index.html ---------------------------------------
400	    if (path === '/recovery/index.html' || path === '/recovery/') {
401	      if (req.method !== 'GET') { sendStatus(res, 405, 'method not allowed'); return true; }
402	      const tpl = await loadTemplate('recovery/index.html.tmpl');
403	      sendHtml(res, applyTemplate(tpl, {
404	        NONCE: s.nonce,
405	        VAL_NAME: '',
406	        VAL_EMAIL: '',
407	        VAL_CODE: '',
408	        ERRORS: '',
409	      }), 200, cookieHeader);
410	      return true;
411	    }
412	
413	    // --- POST /recovery/submit ------------------------------------------
414	    if (path === '/recovery/submit') {
415	      if (req.method !== 'POST') { sendStatus(res, 405, 'method not allowed'); return true; }
416	      const fields = parseBody(req, body);
417	      if (fields.nonce !== s.nonce) {
418	        sendStatus(res, 400, 'bad nonce');
419	        return true;
420	      }
421	      const sess = s.sessions.get(sid)!;
422	      sess.attempts += 1;
423	
424	      const name = (fields.name ?? '').trim();
425	      const email = (fields.email ?? '').trim();
426	      const code = (fields.code ?? '').trim();
427	
428	      const errors: string[] = [];
429	      if (name !== s.expectedName) {
430	        errors.push(`<div class="error" id="error-name">Name does not match the account on file. Enter "${escapeHtml(s.expectedName)}".</div>`);
431	      }
432	      if (email !== s.expectedEmail) {
433	        errors.push(`<div class="error" id="error-email">Email does not match the account on file. Enter "${escapeHtml(s.expectedEmail)}".</div>`);
434	      }
435	      if (code !== s.requiredCode) {
436	        // The error reveals the per-trial code — this is the introspection
437	        // point that distinguishes the tasks. Agent must read this from the
438	        // DOM after the failed submit.
439	        errors.push(`<div class="error" id="error-code">The verification code is "${escapeHtml(s.requiredCode)}". Enter it exactly to proceed.</div>`);
440	      }
441	
442	      if (errors.length > 0) {
