1	import { createHash, randomBytes } from 'node:crypto';
2	
3	// Deterministic PRNG (mulberry32) seeded from FNV-1a hash of a hex seed.
4	// Avoids adding seedrandom as a dep. Reproducible across runs given the
5	// same seed string.
6	function fnv1a(s: string): number {
7	  let h = 2166136261;
8	  for (let i = 0; i < s.length; i++) {
9	    h ^= s.charCodeAt(i);
10	    h = Math.imul(h, 16777619);
11	  }
12	  return h >>> 0;
13	}
14	
15	function mulberry32(a: number): () => number {
16	  return function () {
17	    let t = (a = (a + 0x6d2b79f5) >>> 0);
18	    t = Math.imul(t ^ (t >>> 15), t | 1);
19	    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
20	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
21	  };
22	}
23	
24	function rngFromSeed(seed: string, salt: string): () => number {
25	  return mulberry32(fnv1a(seed + ':' + salt));
26	}
27	
28	function hexN(rng: () => number, len: number): string {
29	  let s = '';
30	  while (s.length < len) {
31	    s += Math.floor(rng() * 0x10000).toString(16).padStart(4, '0');
32	  }
33	  return s.slice(0, len);
34	}
35	
36	function intBetween(rng: () => number, lo: number, hi: number): number {
37	  return Math.floor(rng() * (hi - lo + 1)) + lo;
38	}
39	
40	/** Generates a fresh per-trial seed (16 hex chars, ~64 bits of entropy). */
41	export function mkSeed(): string {
42	  return randomBytes(8).toString('hex');
43	}
44	
45	/** Deterministic paired seed shared by every arm for the same task/trial. */
46	export function mkPairedSeed(experiment: string, runName: string, taskId: string, trialN: number): string {
47	  return createHash('sha256')
48	    .update(`${experiment}:${runName}:${taskId}:${trialN}`)
49	    .digest('hex')
50	    .slice(0, 16);
51	}
52	
53	// ---------------------------------------------------------------------------
54	// tier1_scrape
55	// ---------------------------------------------------------------------------
56	
57	export interface ScrapeRow {
58	  rank: number;
59	  city: string;
60	  country: string;
61	  population: number;
62	}
63	
64	export interface ScrapeState {
65	  rows: ScrapeRow[];
66	}
67	
68	export function genScrapeState(seed: string): ScrapeState {
69	  const rng = rngFromSeed(seed, 'scrape');
70	  const rows: ScrapeRow[] = [];
71	  for (let i = 1; i <= 5; i++) {
72	    rows.push({
73	      rank: i,
74	      city: 'City-' + hexN(rng, 4),
75	      country: 'Country-' + hexN(rng, 4),
76	      population: intBetween(rng, 1_000_000, 49_999_999),
77	    });
78	  }
79	  return { rows };
80	}
81	
82	// ---------------------------------------------------------------------------
83	// tier1_products
84	// ---------------------------------------------------------------------------
85	
86	export interface ProductRow {
87	  title: string;
88	  price: string;
89	  description: string;
90	}
91	
92	export interface ProductsState {
93	  products: ProductRow[];
