43	async function copyStrictPlaywrightSkill(
44	  rootDir: string,
45	  trialWorkDir: string,
46	  runName?: string,
47	): Promise<void> {
48	  const skillDir = join(trialWorkDir, '.claude', 'skills', 'playwright-cli');
49	  await mkdir(skillDir, { recursive: true });
50	  const sourceDir = join(rootDir, '.claude', 'skills', 'playwright-cli');
51	  const variantPath = runName ? join(sourceDir, `SKILL.${runName}.md`) : '';
52	  let raw: string;
53	  try {
54	    raw = variantPath ? await readFile(variantPath, 'utf-8') : await readFile(join(sourceDir, 'SKILL.md'), 'utf-8');
55	  } catch {
56	    raw = await readFile(join(sourceDir, 'SKILL.md'), 'utf-8');
57	  }
58	  const sanitized = raw.replace(
59	    /^allowed-tools:.*$/m,
60	    'allowed-tools: Bash(playwright-cli:*)',
61	  );
62	  await writeFile(join(skillDir, 'SKILL.md'), sanitized, 'utf-8');
63	}
