65	/**
66	 * Builds the argv for `claude` for a given arm. Centralizes the isolation
67	 * convention so verify-arms uses the same logic as runTrial.
68	 *
69	 * Isolation strategy:
70	 *   --strict-mcp-config + --mcp-config <json|file>  : controls MCP exposure
71	 *   --allowed-tools <list>                          : optional strict positive allowlist
72	 *   --disallowed-tools <list>                       : blocks per-arm shortcuts
73	 *   --setting-sources project,local                 : keeps user-level skills out
74	 *   --permission-mode bypassPermissions             : no prompts in -p mode
75	 */
76	export function buildClaudeArgs(
77	  armConfig: ArmConfig,
78	  prompt: string,
79	  model: string,
80	  rootDir: string,
81	  outputFormat: 'text' | 'stream-json' = 'stream-json',
82	): string[] {
83	  const mcpConfig = armConfig.mcpConfig.startsWith('{')
84	    ? armConfig.mcpConfig
85	    : resolve(rootDir, armConfig.mcpConfig);
86	
87	  const args = [
88	    '-p', prompt,
89	    '--output-format', outputFormat,
90	    '--model', model,
91	    '--strict-mcp-config',
92	    '--mcp-config', mcpConfig,
93	  ];
94	
95	  if (outputFormat === 'stream-json') {
96	    args.push('--verbose');
97	  }
98	
99	  if (armConfig.allowedTools && armConfig.allowedTools.length > 0) {
100	    args.push('--allowed-tools', armConfig.allowedTools.join(' '));
101	  }
102	
103	  if (armConfig.disallowedTools.length > 0) {
104	    args.push('--disallowed-tools', armConfig.disallowedTools.join(' '));
105	  }
106	
107	  args.push(...armConfig.extraFlags);
108	
109	  return args;
110	}
