112	export async function runTrial(opts: RunTrialOptions): Promise<TrialResult> {
113	  const {
114	    experiment,
115	    runName,
116	    arm,
117	    task,
118	    trialN,
119	    rootDir,
120	    model = 'claude-sonnet-4-6',
121	    requireSingleCliCommand = false,
122	  } = opts;
123	  const armConfig = getArmConfig(arm, runName);
124	
125	  const artifactsRoot = artifactRoot(rootDir, experiment, runName);
126	  const resultsDir = join(artifactsRoot, 'results', arm, task.id);
127	  const transcriptsDir = join(artifactsRoot, 'transcripts', arm, task.id);
128	  const persistentOutputDir = join(resultsDir, String(trialN));
129	  const fixturesPath = join(rootDir, 'experiments', experiment, 'fixtures');
130	
131	  await mkdir(resultsDir, { recursive: true });
132	  await mkdir(transcriptsDir, { recursive: true });
133	
134	  // Run each trial in a fresh tempdir so the agent has no view of other arms'
135	  // committed artifacts (which it could otherwise discover via Bash + find).
136	  // After the trial we copy the workdir into the persistent results path.
137	  const trialWorkDir = await mkdtemp(join(tmpdir(), `clivsmcp-${arm}-${task.id}-`));
138	
139	  if (runName && arm === 'skill') {
140	    await copyStrictPlaywrightSkill(rootDir, trialWorkDir, runName);
141	  } else if (!runName) {
142	    // Legacy runs keep the original behavior so historical methodology remains
143	    // reproducible. Strict runs copy only the Playwright skill when needed.
144	    await cp(join(rootDir, '.claude'), join(trialWorkDir, '.claude'), { recursive: true });
145	  }
146	
147	  // Per-trial seed → state. Seed lives only in this process and the
148	  // post-hoc result JSON; never written to a file the agent could read
149	  // during the trial. State is opaque to the harness; tasks own its shape.
150	  const seed = runName ? mkPairedSeed(experiment, runName, task.id, trialN) : mkSeed();
151	  const state = task.setup ? await task.setup(seed) : null;
152	
153	  const fixtureServer = await startFixtureServer(
154	    fixturesPath,
155	    task.renderResponse
156	      ? (req, res, body) => task.renderResponse!(state, req, res, body)
157	      : undefined,
158	  );
159	  const ctx: TaskContext = {
160	    rootDir,
161	    fixturesPath,
162	    fixturesUrl: fixtureServer.url,
163	    outputDir: trialWorkDir,
164	    state,
165	  };
166	  const timestamp = new Date().toISOString();
167	  let prompt = task.prompt(ctx);
168	  if (runName && arm === 'skill' && requireSingleCliCommand) {
169	    prompt += '\n\nStrict research accounting requirement: use exactly one playwright-cli command per Bash tool call. Do not chain commands with &&, ;, pipes, redirects, or shell substitutions.';
170	  }
171	  const args = buildClaudeArgs(armConfig, prompt, model, rootDir, 'stream-json');
172	
173	  let transcriptLines: string[] = [];
174	  let stderrText = '';
175	  let cliError: string | undefined;
176	
177	  // Per-trial wall-clock cap. Claude Code 2.1 exposes no --max-turns flag,
178	  // so we bound runaway cost (mostly baseline, which loops on doomed escape
179	  // attempts) at the process level. Skill/mcp typically finish in <70s, so
180	  // 180s leaves comfortable headroom; baseline gets killed mid-loop and its
181	  // successCheck fails as expected.
182	  const TRIAL_TIMEOUT_MS = 180_000;
183	
184	  try {
185	    const result = await execa('claude', args, {
186	      cwd: trialWorkDir,  // isolate cwd from project tree
187	      reject: false,
188	      stdin: 'ignore',
189	      timeout: TRIAL_TIMEOUT_MS,
190	    });
191	
192	    transcriptLines = (result.stdout ?? '').split('\n');
193	    stderrText = result.stderr ?? '';
194	
195	    if (result.timedOut) {
196	      cliError = `claude timed out after ${TRIAL_TIMEOUT_MS}ms`;
197	    } else if (result.exitCode !== 0) {
198	      cliError = stderrText || `claude exited with code ${result.exitCode}`;
199	    }
200	  } catch (err) {
201	    cliError = err instanceof Error ? err.message : String(err);
202	  } finally {
203	    await fixtureServer.close().catch(() => undefined);
204	  }
205	
206	  await writeFile(
207	    join(transcriptsDir, `${trialN}.jsonl`),
208	    transcriptLines.join('\n'),
209	    'utf-8',
210	  );
211	
212	  if (stderrText.trim()) {
213	    await writeFile(join(transcriptsDir, `${trialN}.stderr.log`), stderrText, 'utf-8');
214	  }
215	
216	  // Move agent artifacts from tempdir to the persistent output dir, then
217	  // run successCheck against the persistent location. The `.claude/` we
218	  // injected for skill auto-discovery is excluded — it's just a copy of
219	  // the project's skills config, not an artifact the agent produced.
220	  await rm(persistentOutputDir, { recursive: true, force: true });
221	  await cp(trialWorkDir, persistentOutputDir, {
222	    recursive: true,
223	    filter: (src) => !src.includes(`${sep}.claude`),
224	  });
225	  await rm(trialWorkDir, { recursive: true, force: true });
226	
227	  const persistentCtx: TaskContext = { ...ctx, outputDir: persistentOutputDir };
228	
229	  const metrics = parseTranscript(transcriptLines, arm);
230	
231	  let success: SuccessResult;
232	  try {
233	    success = await task.successCheck(persistentCtx);
234	  } catch (err) {
235	    success = {
236	      pass: false,
237	      score: 0,
238	      notes: `successCheck threw: ${err instanceof Error ? err.message : String(err)}`,
239	    };
240	  }
241	
242	  const trialResult: TrialResult = {
243	    experiment,
244	    ...(runName ? { runName } : {}),
245	    arm,
246	    taskId: task.id,
247	    tier: task.tier,
248	    trialN,
249	    timestamp,
250	    seed,
251	    metrics,
252	    success,
253	    ...(cliError ? { error: cliError } : {}),
254	  };
255	
256	  await writeFile(
257	    join(resultsDir, `${trialN}.json`),
258	    JSON.stringify(trialResult, null, 2),
259	    'utf-8',
260	  );
261	
262	  return trialResult;
263	}
