  runName?: string,
): Promise<void> {
  const skillDir = join(trialWorkDir, '.claude', 'skills', 'playwright-cli');
  await mkdir(skillDir, { recursive: true });
  const sourceDir = join(rootDir, '.claude', 'skills', 'playwright-cli');
  const variantPath = runName ? join(sourceDir, `SKILL.${runName}.md`) : '';
  let raw: string;
  try {
    raw = variantPath ? await readFile(variantPath, 'utf-8') : await readFile(join(sourceDir, 'SKILL.md'), 'utf-8');
  } catch {
    raw = await readFile(join(sourceDir, 'SKILL.md'), 'utf-8');
  }
  const sanitized = raw.replace(
    /^allowed-tools:.*$/m,
    'allowed-tools: Bash(playwright-cli:*)',
  );
  await writeFile(join(skillDir, 'SKILL.md'), sanitized, 'utf-8');
}

/**
 * Builds the argv for `claude` for a given arm. Centralizes the isolation
 * convention so verify-arms uses the same logic as runTrial.
 *
 * Isolation strategy:
 *   --strict-mcp-config + --mcp-config <json|file>  : controls MCP exposure
 *   --allowed-tools <list>                          : optional strict positive allowlist
 *   --disallowed-tools <list>                       : blocks per-arm shortcuts
 *   --setting-sources project,local                 : keeps user-level skills out
 *   --permission-mode bypassPermissions             : no prompts in -p mode
 */
export function buildClaudeArgs(
  armConfig: ArmConfig,
  prompt: string,
  model: string,
  rootDir: string,
  outputFormat: 'text' | 'stream-json' = 'stream-json',
): string[] {
  const mcpConfig = armConfig.mcpConfig.startsWith('{')
    ? armConfig.mcpConfig
    : resolve(rootDir, armConfig.mcpConfig);

  const args = [
    '-p', prompt,
    '--output-format', outputFormat,
    '--model', model,
    '--strict-mcp-config',
    '--mcp-config', mcpConfig,
  ];

  if (outputFormat === 'stream-json') {
    args.push('--verbose');
  }

  if (armConfig.allowedTools && armConfig.allowedTools.length > 0) {
    args.push('--allowed-tools', armConfig.allowedTools.join(' '));
  }

  if (armConfig.disallowedTools.length > 0) {
    args.push('--disallowed-tools', armConfig.disallowedTools.join(' '));
  }

  args.push(...armConfig.extraFlags);

  return args;
}

export async function runTrial(opts: RunTrialOptions): Promise<TrialResult> {
  const {
    experiment,
    runName,
    arm,
    task,
    trialN,
    rootDir,
    model = 'claude-sonnet-4-6',
    requireSingleCliCommand = false,
  } = opts;
  const armConfig = getArmConfig(arm, runName);

  const artifactsRoot = artifactRoot(rootDir, experiment, runName);
  const resultsDir = join(artifactsRoot, 'results', arm, task.id);
  const transcriptsDir = join(artifactsRoot, 'transcripts', arm, task.id);
  const persistentOutputDir = join(resultsDir, String(trialN));
  const fixturesPath = join(rootDir, 'experiments', experiment, 'fixtures');

  await mkdir(resultsDir, { recursive: true });
  await mkdir(transcriptsDir, { recursive: true });

  // Run each trial in a fresh tempdir so the agent has no view of other arms'
  // committed artifacts (which it could otherwise discover via Bash + find).
  // After the trial we copy the workdir into the persistent results path.
  const trialWorkDir = await mkdtemp(join(tmpdir(), `clivsmcp-${arm}-${task.id}-`));

  if (runName && arm === 'skill') {
    await copyStrictPlaywrightSkill(rootDir, trialWorkDir, runName);
  } else if (!runName) {
    // Legacy runs keep the original behavior so historical methodology remains
    // reproducible. Strict runs copy only the Playwright skill when needed.
    await cp(join(rootDir, '.claude'), join(trialWorkDir, '.claude'), { recursive: true });
  }

  // Per-trial seed → state. Seed lives only in this process and the
  // post-hoc result JSON; never written to a file the agent could read
  // during the trial. State is opaque to the harness; tasks own its shape.
  const seed = runName ? mkPairedSeed(experiment, runName, task.id, trialN) : mkSeed();
  const state = task.setup ? await task.setup(seed) : null;

  const fixtureServer = await startFixtureServer(
    fixturesPath,
    task.renderResponse
      ? (req, res, body) => task.renderResponse!(state, req, res, body)
      : undefined,
  );
  const ctx: TaskContext = {
    rootDir,
    fixturesPath,
    fixturesUrl: fixtureServer.url,
    outputDir: trialWorkDir,
    state,
  };
  const timestamp = new Date().toISOString();
  let prompt = task.prompt(ctx);
  if (runName && arm === 'skill' && requireSingleCliCommand) {
    prompt += '\n\nStrict research accounting requirement: use exactly one playwright-cli command per Bash tool call. Do not chain commands with &&, ;, pipes, redirects, or shell substitutions.';
  }
  const args = buildClaudeArgs(armConfig, prompt, model, rootDir, 'stream-json');

  let transcriptLines: string[] = [];
  let stderrText = '';
  let cliError: string | undefined;

  // Per-trial wall-clock cap. Claude Code 2.1 exposes no --max-turns flag,
  // so we bound runaway cost (mostly baseline, which loops on doomed escape
  // attempts) at the process level. Skill/mcp typically finish in <70s, so
  // 180s leaves comfortable headroom; baseline gets killed mid-loop and its
  // successCheck fails as expected.
  const TRIAL_TIMEOUT_MS = 180_000;

  try {
    const result = await execa('claude', args, {
      cwd: trialWorkDir,  // isolate cwd from project tree
      reject: false,
      stdin: 'ignore',
      timeout: TRIAL_TIMEOUT_MS,
    });

    transcriptLines = (result.stdout ?? '').split('\n');
    stderrText = result.stderr ?? '';

    if (result.timedOut) {
      cliError = `claude timed out after ${TRIAL_TIMEOUT_MS}ms`;
    } else if (result.exitCode !== 0) {
      cliError = stderrText || `claude exited with code ${result.exitCode}`;
    }
  } catch (err) {
    cliError = err instanceof Error ? err.message : String(err);
  } finally {
    await fixtureServer.close().catch(() => undefined);
  }

  await writeFile(
    join(transcriptsDir, `${trialN}.jsonl`),
    transcriptLines.join('\n'),
    'utf-8',
  );

  if (stderrText.trim()) {
    await writeFile(join(transcriptsDir, `${trialN}.stderr.log`), stderrText, 'utf-8');
  }

  // Move agent artifacts from tempdir to the persistent output dir, then
  // run successCheck against the persistent location. The `.claude/` we
  // injected for skill auto-discovery is excluded — it's just a copy of
  // the project's skills config, not an artifact the agent produced.
  await rm(persistentOutputDir, { recursive: true, force: true });
  await cp(trialWorkDir, persistentOutputDir, {
    recursive: true,
    filter: (src) => !src.includes(`${sep}.claude`),
  });
  await rm(trialWorkDir, { recursive: true, force: true });

  const persistentCtx: TaskContext = { ...ctx, outputDir: persistentOutputDir };

  const metrics = parseTranscript(transcriptLines, arm);

  let success: SuccessResult;
  try {
    success = await task.successCheck(persistentCtx);
  } catch (err) {
    success = {
      pass: false,
      score: 0,
      notes: `successCheck threw: ${err instanceof Error ? err.message : String(err)}`,
    };
  }

  const trialResult: TrialResult = {
    experiment,
    ...(runName ? { runName } : {}),
    arm,
    taskId: task.id,
    tier: task.tier,
    trialN,
    timestamp,
    seed,
    metrics,
    success,
    ...(cliError ? { error: cliError } : {}),
  };

  await writeFile(
    join(resultsDir, `${trialN}.json`),
    JSON.stringify(trialResult, null, 2),
    'utf-8',
  );

  return trialResult;
}

